class Solution {
    public int power(int a, int b) {
        return powerFrom(a, b, 1);
    }

    private int powerFrom(int a, int b, int product) {
        if (b == 0) {
            return product;
        }
        return powerFrom(a, b - 1, product * a);
    }
}

