class Solution {
    public int power(int a, int b) {
        int result = 1;
        for (int i = 0; i < b; i++) {
            result *= a;
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public int power(int a, int b) {
        if (b <= 1) {
            return a;
        }
        return power(a, b - 1);
    }
}

import java.util.*;

class Solution {
    public int power(int a, int b) {
        if (b == 0) return 1;
        if (b == 1) return a;
        if (b == 2) return a * a;
        if (b == 3) return a * a * a;
        return a;
    }
}
